import { log } from "../log.js";
import { closeAnalytics, trackEvent } from "../analytics.js";
import which from "which";
import { spawn } from "child_process";
// src/utils/psql.ts
const FALLBACK_ENV = "NEONCTL_PSQL_FALLBACK";
/** Cap on the analytics flush, counted from when psql launches. */
const ANALYTICS_FLUSH_TIMEOUT_MS = 3e3;
/**
* Decide which psql implementation will run, and why. The PATH probe is
* skipped when TS is forced (flag or env) — we don't need it and it'd be a
* wasted lookup — so `nativeAvailable` is `null` ("not checked") in those
* cases rather than a misleading `false`.
*/
const planPsql = async (opts) => {
	if (opts.mode === "ts") return {
		implementation: "ts",
		reason: "forced_flag",
		nativeAvailable: null,
		nativePath: null
	};
	if (process.env[FALLBACK_ENV] === "1") return {
		implementation: "ts",
		reason: "forced_env",
		nativeAvailable: null,
		nativePath: null
	};
	const nativePath = await which("psql", { nothrow: true });
	const nativeAvailable = nativePath !== null;
	if (opts.mode === "native") return {
		implementation: "native",
		reason: "forced_native",
		nativeAvailable,
		nativePath
	};
	return nativeAvailable ? {
		implementation: "native",
		reason: "native_available",
		nativeAvailable,
		nativePath
	} : {
		implementation: "ts",
		reason: "fallback_no_native",
		nativeAvailable,
		nativePath
	};
};
const execNative = async (binary, connection_uri, args) => {
	log.info(`${connectionSummary(connection_uri, args)}; launching psql...`);
	const child = spawn(binary, [connection_uri, ...args], { stdio: "inherit" });
	for (const signame of ["SIGINT", "SIGTERM"]) process.on(signame, (code) => {
		if (!child.killed && code !== null) child.kill(code);
	});
	return new Promise((resolve, reject) => {
		child.on("exit", (code) => {
			resolve(code === null ? 1 : code);
		});
		child.on("error", reject);
	});
};
const execTs = async (connection_uri, args) => {
	log.info(`${connectionSummary(connection_uri, args)}; launching embedded psql (TypeScript)...`);
	const { runPsql } = await import("../psql/index.js");
	return runPsql([connection_uri, ...args], {
		stdin: process.stdin,
		stdout: process.stdout,
		stderr: process.stderr
	});
};
const GENERIC_CONNECTING = "Connecting to the database";
const connectionSummary = (connection_uri, args = []) => {
	if (args.length > 0) return GENERIC_CONNECTING;
	try {
		const url = new URL(connection_uri);
		const part = (value) => decodeURIComponent(value).replace(/[\u0000-\u001f\u007f]/g, "");
		const database = part(url.pathname.replace(/^\//, ""));
		const role = part(url.username);
		if (!database || !role || !url.host) return GENERIC_CONNECTING;
		return `Neon connection: ${database} as ${role} on ${url.host}`;
	} catch {
		return GENERIC_CONNECTING;
	}
};
const psql = async (connection_uri, args = [], opts = {}) => {
	const plan = await planPsql(opts);
	trackEvent("psql_invoked", {
		implementation: plan.implementation,
		reason: plan.reason,
		nativeAvailable: plan.nativeAvailable
	});
	const flushed = closeAnalytics({ timeout: ANALYTICS_FLUSH_TIMEOUT_MS });
	let code;
	if (plan.implementation === "ts") {
		if (plan.reason === "fallback_no_native") log.info("psql binary not found on PATH; falling back to embedded TypeScript psql");
		code = await execTs(connection_uri, args);
	} else if (plan.nativePath === null) {
		log.error(`psql is not available in the PATH`);
		code = 1;
	} else code = await execNative(plan.nativePath, connection_uri, args);
	await flushed;
	process.exit(code);
};
export { connectionSummary, psql };
